use super::kit::*;
pub fn commands()->Vec<Command>{vec![
Command{name:"inspect_grade_scopes",description:"Read project shared graph registry, ordered clip/group bindings and final timeline chain. Scope graph definitions editable with add_node, connect_nodes or set_node_param passing shared_graph_id instead of clip_id.",mutates:false,schema:obj(vec![],&[]),run:|ss,_|Ok(json!({"scopes":ss.project.grade_scopes,"order":"legacy clip effects -> local graph -> clip shared refs -> groups in stored order -> clip mask/transform/composite -> timeline refs -> output transform","clock":"clip/group references use clip-local time; timeline uses composition time; nested composition timeline chain suppressed","cache":"definitions shared, evaluated pixel caches NOT shared across clips"}))},
Command{name:"set_grade_scopes",description:"Replace complete scope JSON: graphs registry, clip_bindings, ordered groups(id/clips/graphs/bypass), timeline ordered refs. Full MCP access to membership/order/bypass and definitions. Validates references and graph domains transactionally; no inferred group or timeline color domain.",mutates:true,schema:obj(vec![("scopes",json!({"type":"object"}))],&["scopes"]),run:|ss,a|{let v:crate::color::grade_scopes::Scopes=serde_json::from_value(a.get("scopes").ok_or("scopes required")?.clone()).map_err(|e|e.to_string())?;v.validate(&ss.project)?;ss.project.grade_scopes=v;Ok(json!({"ok":true}))}},
Command{name:"create_shared_grade_graph",description:"Create named shared grade definition, optionally full graph, otherwise input identity. Edit it with add_node, connect_nodes or set_node_param passing shared_graph_id. No references automatically assigned.",mutates:true,schema:obj(vec![("id",s("unique registry identity")),("graph",json!({"type":"object"}))],&["id"]),run:|ss,a|{let id=str_arg(a,"id")?;if ss.project.grade_scopes.graphs.contains_key(id){return Err("shared identity exists".into())}let g:crate::color::node_graph::Graph=serde_json::from_value(a.get("graph").cloned().unwrap_or(serde_json::to_value(crate::color::node_graph::Graph::default()).unwrap())).map_err(|e|e.to_string())?;g.validate_project(&ss.project)?;let mut scopes=ss.project.grade_scopes.clone();scopes.graphs.insert(id.into(),g);scopes.validate(&ss.project)?;ss.project.grade_scopes=scopes;Ok(json!({"shared_graph_id":id}))}},
Command{name:"bind_shared_grade_graphs",description:"Assign ordered shared graph refs to a clip (also adjustment/precomp clips). Empty array clears. Applied after local graph. Full group/timeline binding via set_grade_scopes.",mutates:true,schema:obj(vec![("clip_id",s("existing clip")),("graphs",json!({"type":"array","items":{"type":"string"}}))],&["clip_id","graphs"]),run:|ss,a|{let id=str_arg(a,"clip_id")?;let refs:Vec<String>=serde_json::from_value(a.get("graphs").ok_or("graphs required")?.clone()).map_err(|e|e.to_string())?;let mut scopes=ss.project.grade_scopes.clone();if refs.is_empty(){scopes.clip_bindings.remove(id);}else{scopes.clip_bindings.insert(id.into(),refs);}scopes.validate(&ss.project)?;ss.project.grade_scopes=scopes;Ok(json!({"ok":true}))}},
Command{name:"remove_shared_grade_graph",description:"Remove only an unreferenced shared graph. Clear clip/group/timeline refs first; refuses dangling deletes.",mutates:true,schema:obj(vec![("id",s("registry identity"))],&["id"]),run:|ss,a|{let mut scopes=ss.project.grade_scopes.clone();scopes.graphs.remove(str_arg(a,"id")?).ok_or("missing shared graph")?;scopes.validate(&ss.project)?;ss.project.grade_scopes=scopes;Ok(json!({"ok":true}))}}
]}
